// coerceIntFlag parses an integer-typed flag that the OpenAPI anyOf flattening
// emitted as a string. Empty values fall through so defaults stay untouched.
func coerceIntFlag(raw string) (any, error) {
	if strings.TrimSpace(raw) == "" {
		return nil, nil
	}
	n, err := strconv.Atoi(strings.TrimSpace(raw))
	if err != nil {
		return nil, fmt.Errorf("expected an integer, got %q", raw)
	}
	return n, nil
}

// coerceBoolFlag parses a boolean-typed flag emitted as a string by the
// OpenAPI anyOf flattening. Empty values fall through.
func coerceBoolFlag(raw string) (any, error) {
	if strings.TrimSpace(raw) == "" {
		return nil, nil
	}
	switch strings.ToLower(strings.TrimSpace(raw)) {
	case "true", "1", "yes":
		return true, nil
	case "false", "0", "no":
		return false, nil
	default:
		return nil, fmt.Errorf("expected true or false, got %q", raw)
	}
}

